49	/** Run `fn`, retrying on failure with exponential backoff; every attempt is logged. */
50	async function withRetry<T>(label: string, fn: () => Promise<T>, o: RetryOpts): Promise<T> {
51	  const total = o.retries + 1;
52	  for (let attempt = 1; ; attempt++) {
53	    o.log("[fetch] " + label + ": attempt " + attempt + "/" + total);
54	    try {
55	      return await fn();
56	    } catch (e) {
57	      if (attempt >= total) throw e;
58	      o.log("[fetch] " + label + ": attempt " + attempt + " failed (" + (e as Error).message + "); retrying");
59	      await sleep(o.backoffMs * 2 ** (attempt - 1));
60	    }
61	  }
62	}
