71	  // One round trip: remote HEAD plus the two places checkpoint data can live.
72	  const lsOut = await withRetry("ls-remote", () => git(["ls-remote", src, "HEAD", branchRef, CHECKPOINT_REFS + "*"]), o);
73	  const lines = lsOut
74	    .split("\n")
75	    .filter(Boolean)
76	    .map((l) => l.split("\t") as [string, string]);
77	  const remoteHead = lines.find(([, ref]) => ref === "HEAD")?.[0] ?? "";
78	  const hasBranch = lines.some(([, ref]) => ref === branchRef);
79	  const hasRefs = lines.some(([, ref]) => ref.startsWith(CHECKPOINT_REFS));
