88	  const metaPath = join(repoPath, ".git", META_FILE);
89	  if (existsSync(metaPath)) {
90	    o.log("[fetch] cache hit " + key);
91	    return JSON.parse(readFileSync(metaPath, "utf8")) as FetchResult;
92	  }
93	
94	  mkdirSync(cacheDir, { recursive: true });
95	  const tmp = repoPath + ".tmp-" + process.pid;
96	  await withRetry(
97	    "clone",
98	    async () => {
99	      rmSync(tmp, { recursive: true, force: true });
100	      await git(["clone", "--quiet", "--filter=blob:none", "--no-checkout", src, tmp]);
101	    },
102	    o,
103	  );
104	
105	  let backend: Backend = "none";
106	  if (hasBranch) {
107	    const spec = "+" + CHECKPOINT_BRANCH + ":" + CHECKPOINT_BRANCH;
108	    await withRetry("fetch branch", () => git(["fetch", "--quiet", "origin", spec], tmp), o);
109	    backend = "branch";
110	  } else if (hasRefs) {
111	    const spec = "+" + CHECKPOINT_REFS + "*:" + CHECKPOINT_REFS + "*";
112	    await withRetry("fetch refs", () => git(["fetch", "--quiet", "origin", spec], tmp), o);
113	    backend = "refs";
114	  } else {
115	    o.log("[fetch] no Entire data: run `entire enable` in the source repo and push the checkpoints branch");
116	  }
