120	    headSha = (await git(["rev-parse", "HEAD"], tmp)).trim();
121	  } catch {
122	    // empty repository: no HEAD
123	  }
124	
125	  const result: FetchResult = { repoPath, backend, headSha };
126	  writeFileSync(join(tmp, ".git", META_FILE), JSON.stringify(result));
127	  rmSync(repoPath, { recursive: true, force: true });
128	  renameSync(tmp, repoPath);
